// Minimal NoSleep shim.
// Wake Lock API requires a SECURE context; http://<lan-ip> is not one, so
// `navigator.wakeLock` doesn't even exist there — the old version of this
// file only tried that API, which made it a silent no-op on the phone over
// LAN (all the real keep-awake work was left to Android's "Stay awake while
// charging" developer option, see README). Devices/ROMs that hide that
// setting had no fallback at all. This adds one: a hidden <video> fed by
// canvas.captureStream(), which doesn't need a secure context — Android
// Chromium treats a page with actively "playing" video as active media
// playback and defers screen timeout for it, the same trick the classic
// NoSleep.js library used before the Wake Lock API existed.
(function () {
  function NoSleep() {
    this._wakeLock = null;
    this._enabled = false;
    this._video = null;
    this._paintTimer = null;
    var self = this;
    this._onVis = function () {
      if (!self._enabled || document.visibilityState !== "visible") return;
      if ("wakeLock" in navigator) {
        self._requestWakeLock();
      } else if (self._video) {
        var p = self._video.play();
        if (p && p.catch) p.catch(function () {});
      }
    };
  }

  NoSleep.prototype._requestWakeLock = function () {
    var self = this;
    navigator.wakeLock.request("screen").then(function (wl) {
      self._wakeLock = wl;
    }).catch(function () {});
  };

  NoSleep.prototype._startVideoFallback = function () {
    if (this._video) return;
    var canvas = document.createElement("canvas");
    if (!canvas.captureStream) return; // nothing more we can do on this browser
    canvas.width = 2;
    canvas.height = 2;
    var ctx = canvas.getContext("2d");
    if (ctx) ctx.fillRect(0, 0, 2, 2);
    var stream = canvas.captureStream(0); // 0fps: only emits a frame when asked
    var track = stream.getVideoTracks()[0];

    var video = document.createElement("video");
    video.setAttribute("playsinline", "");
    video.setAttribute("aria-hidden", "true");
    video.muted = true;
    video.loop = true;
    video.style.cssText = "position:fixed;left:-9999px;top:-9999px;width:1px;height:1px;opacity:0;";
    video.srcObject = stream;
    document.body.appendChild(video);
    var p = video.play();
    if (p && p.catch) p.catch(function () {});

    // Some engines only suppress sleep while the stream is actively producing
    // frames — nudge one periodically so a 0fps canvas stream still counts.
    this._paintTimer = setInterval(function () {
      try {
        if (track && track.requestFrame) track.requestFrame();
        else if (ctx) ctx.fillRect(0, 0, 2, 2);
      } catch (e) {}
    }, 1000);
    this._video = video;
  };

  NoSleep.prototype.enable = function () {
    if (this._enabled) return;
    this._enabled = true;
    if ("wakeLock" in navigator) {
      this._requestWakeLock();
      document.addEventListener("visibilitychange", this._onVis);
    } else {
      this._startVideoFallback();
      document.addEventListener("visibilitychange", this._onVis);
    }
  };
  NoSleep.prototype.disable = function () {
    this._enabled = false;
    if (this._wakeLock) { this._wakeLock.release(); this._wakeLock = null; }
    document.removeEventListener("visibilitychange", this._onVis);
    if (this._paintTimer) { clearInterval(this._paintTimer); this._paintTimer = null; }
    if (this._video) { this._video.pause(); this._video.remove(); this._video = null; }
  };
  window.NoSleep = NoSleep;
})();
